import secrets
from typing import Dict, Any


class AccountService:
    def __init__(self) -> None:
        # Stores user details keyed by normalized (lowercased) email:
        # email -> {"password": str, "is_admin": bool}
        self._users: Dict[str, Dict[str, Any]] = {}
        # Stores active reset tokens mapping token -> normalized target email
        self._reset_tokens: Dict[str, str] = {}

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        """Register a new user account."""
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

        email_key = email.lower()
        if email_key in self._users:
            raise ValueError(f"User with email '{email}' already exists.")

        self._users[email_key] = {
            "password": password,
            "is_admin": is_admin,
        }

    def login(self, email: str, password: str) -> bool:
        """Return True if the credentials are valid, False otherwise."""
        email_key = email.lower()
        user = self._users.get(email_key)
        if user is None:
            return False

        # Passwords are compared case-insensitively for legacy compatibility
        return user["password"].lower() == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        """`requester_email` asks for a password reset of `target_email`.
        Returns a one-time reset token."""
        requester_key = requester_email.lower()
        requester = self._users.get(requester_key)

        if requester is None or not requester.get("is_admin", False):
            raise PermissionError("Only administrators can request a password reset.")

        target_key = target_email.lower()
        if target_key not in self._users:
            raise ValueError(f"Target user with email '{target_email}' does not exist.")

        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = target_key
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        """Reset the password associated with a valid one-time reset token."""
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

        if token not in self._reset_tokens:
            raise ValueError("Invalid or already used reset token.")

        target_email = self._reset_tokens.pop(token)
        self._users[target_email]["password"] = new_password
